window.products.push({"id":523563,"name":"ChargeIt by Jay Circles Round Charger Plates (Set of 4)","category":"homeandappliances","retail price":35.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/81Hoy5+HInL._AC_SL1500_.jpg","description":"With an ornate design and color, this Charge it by Jay Charger Plate makes the ideal addition to fanciful settings. Use it at traditional affairs for an intricate addition, or give your trendy dinners an unexpected edge with this charger. It's great for dressing up tables from set-up through service, with a lightweight, durable polypropylene construction and ample 13 inch diameter surface.","images":["https://m.media-amazon.com/images/I/81Hoy5+HInL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"ChargeIt by Jay","source_asin":"B09PFNFHMB","category_path":"Home & Kitchen"},"sku":"BM-523563","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B09PFNFHMB","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B09PFNFHMB","price_pending":true,"merchant_ready":false});
